-- ============================================================================
-- Query Lab dataset: shop
-- An online store: 2 years of orders (2024-2025) with seasonality, returns and reviews.
--
-- Generated by tools/gen_query_lab_data.py (deterministic; do not edit by hand).
-- Load into the lab Postgres:   psql "postgresql://dsa:dsa@localhost:5544/dsa" -f content/data-and-apis/SQL/lab/datasets/shop.sql
-- Then:                         SET search_path TO shop;
-- Tables: customers, categories, products, orders, order_items, payments, reviews
-- ============================================================================
DROP SCHEMA IF EXISTS shop CASCADE;
CREATE SCHEMA shop;
SET search_path TO shop;


CREATE TABLE customers (
    customer_id      INT PRIMARY KEY,
    first_name       TEXT NOT NULL,
    last_name        TEXT NOT NULL,
    email            TEXT NOT NULL UNIQUE,
    phone            TEXT,
    city             TEXT NOT NULL,
    region           TEXT NOT NULL,
    country          TEXT NOT NULL,
    signup_at        TIMESTAMPTZ NOT NULL,
    referred_by      INT REFERENCES customers(customer_id),
    segment          TEXT NOT NULL CHECK (segment IN ('consumer', 'business', 'vip')),
    marketing_opt_in BOOLEAN NOT NULL
);
CREATE TABLE categories (
    category_id INT PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    parent_id   INT REFERENCES categories(category_id)
);
CREATE TABLE products (
    product_id  INT PRIMARY KEY,
    sku         TEXT NOT NULL UNIQUE,
    name        TEXT NOT NULL,
    brand       TEXT NOT NULL,
    category_id INT NOT NULL REFERENCES categories(category_id),
    price       NUMERIC(10,2) NOT NULL CHECK (price > 0),
    cost        NUMERIC(10,2) NOT NULL,
    stock       INT NOT NULL CHECK (stock >= 0),
    attributes  JSONB NOT NULL DEFAULT '{}',
    launched_at DATE NOT NULL,
    is_active   BOOLEAN NOT NULL
);
CREATE TABLE orders (
    order_id       INT PRIMARY KEY,
    customer_id    INT NOT NULL REFERENCES customers(customer_id),
    ordered_at     TIMESTAMPTZ NOT NULL,
    status         TEXT NOT NULL CHECK (status IN ('placed', 'shipped', 'delivered', 'cancelled', 'returned')),
    ship_city      TEXT NOT NULL,
    ship_country   TEXT NOT NULL,
    payment_method TEXT NOT NULL,
    coupon_code    TEXT,
    shipping_fee   NUMERIC(8,2) NOT NULL,
    total_amount   NUMERIC(10,2) NOT NULL,
    delivered_at   TIMESTAMPTZ
);
CREATE TABLE order_items (
    order_id     INT NOT NULL REFERENCES orders(order_id),
    line_no      INT NOT NULL,
    product_id   INT NOT NULL REFERENCES products(product_id),
    quantity     INT NOT NULL CHECK (quantity > 0),
    unit_price   NUMERIC(10,2) NOT NULL,
    discount_pct INT NOT NULL DEFAULT 0,
    PRIMARY KEY (order_id, line_no)
);
CREATE TABLE payments (
    payment_id INT PRIMARY KEY,
    order_id   INT NOT NULL REFERENCES orders(order_id),
    method     TEXT NOT NULL,
    amount     NUMERIC(10,2) NOT NULL,
    status     TEXT NOT NULL CHECK (status IN ('captured', 'pending', 'refunded')),
    paid_at    TIMESTAMPTZ NOT NULL
);
CREATE TABLE reviews (
    review_id         INT PRIMARY KEY,
    product_id        INT NOT NULL REFERENCES products(product_id),
    customer_id       INT NOT NULL REFERENCES customers(customer_id),
    rating            INT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    title             TEXT NOT NULL,
    verified_purchase BOOLEAN NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL,
    UNIQUE (customer_id, product_id)
);


CREATE INDEX ON orders (customer_id);
CREATE INDEX ON orders (ordered_at);
CREATE INDEX ON order_items (product_id);
CREATE INDEX ON reviews (product_id);
ANALYZE;
